fast_pseudocode:
# After: maxnreg=40 cap, higher occupancy, but spills dominate
@triton.autotune(configs=[
    triton.Config({'BLOCK_SIZE': 4096}, num_warps=2, num_stages=4, maxnreg=40),
    triton.Config({'BLOCK_SIZE': 8192}, num_warps=8, num_stages=4, maxnreg=40),
    triton.Config({'BLOCK_SIZE': 8192}, num_warps=16, num_stages=4, maxnreg=40),
    # ... num_warps in {2,4,8,16}, all with maxnreg=40
], key=['n_elements'])
@triton.jit
def kernel(...):
    # 40 registers/thread -> Block Limit Registers=24 -> 75% occupancy
    # BUT: local memory spills -> uncoalesced L1/L2 traffic
    # Warp cycles/instruction: 25.66 -> 90.74, duration=5.94ms (2x slower)
